\label{T1}
If $f\colon X\to \mathbb S^1$ is a tame map and $\xi_f\in H^1(X;\mathbb Z)$ is the integral cohomology class represented by $f$ then: 
\begin{enumerate}[(a)]
\item\label{T1:a}
$\sharp\mathcal B^c_r(f)+\sharp\mathcal B^o_{r-1}(f)$ is a homotopy invariant of the pair $(X,\xi_f)$, 
more precisely is equal to the Novikov--Betti number $\beta^N_r(X;\xi_f)$.                          
\item\label{T1:b}
The collection $\mathcal J_r(f)$ is a homotopy invariant of the pair $(X,\xi_f)$. 
More precisely, $\bigoplus_{J\in \mathcal J_r(f)}J := \bigoplus_{J\in \mathcal J_r(f)}(V_J,T_J) $ 
is the $r$-monodromy $(V_r, T_r)$ of $(X;\xi_f)$.                          
\item\label{T1:c}
$\sharp \mathcal B^c_r(f)+\sharp \mathcal B^o_{r-1}(f)+\sharp \mathcal J_{r,1}(f)+\sharp \mathcal J_{r-1,1}(f)$ is equal to the Betti number $\beta_r(X)$.
\end{enumerate}

\label {T5}
The assignment $f\mapsto C^m_r(f)$ is a continuous map from the space $C_t(X,\mathbb S^1)$ of tame maps to $\mathcal\operatorname{Confg}(\mathbb T\setminus \Delta_{\mathbb T})$ 
when the first space is equipped with the compact open topology and the second with the topology  described above in case $(X,K)= (\mathbb T, \Delta_{\mathbb T})$.

\label{O41}
(a) If $\rho$ is a $G_{2m}$-representation then 
$$
\mathcal B(\tilde \rho)=\tilde{\mathcal B}(\rho),\qquad\mathcal J(\tilde \rho)=\tilde{\mathcal J}(\rho),
$$
$$
\mathcal B^c(\tilde \rho)=\tilde{\mathcal B}^c(\rho),\quad
\mathcal B^o(\tilde \rho)=\tilde{\mathcal B}^o(\rho),\quad
\mathcal B^{co}(\tilde \rho)=\tilde{\mathcal B}^{co}(\rho),\quad
\mathcal B^{oc}(\tilde \rho)=\tilde{\mathcal B}^{oc}(\rho),
$$
and:
\begin{equation*}
\begin{aligned}
\mathcal B^c(T_{k,l}(\rho))&=\{I\cap[k,l]:\text{$I\in\tilde{\mathcal B}(\rho)$ such that $I\cap [k, l]$ is non-empty and closed}\}
\\&\qquad \sqcup \{\text{$[k,l]$ with multiplicity $\sharp\tilde{\mathcal J}(\rho)$}\},
\\
\mathcal B^o(T_{k,l}(\rho))&=\{I\in\tilde{\mathcal B}^o(\rho): I\subset [k,l] \}
\\
\mathcal J(T_{k,l}(\rho))&=\emptyset.                                       
\end{aligned}
\end{equation*}


(b) If $\rho$ is a good $\mathcal Z$-representation then:
\begin{equation*}
\begin{aligned}
\mathcal B^c(T_{k,l}(\rho))&=\{I\cap[k,l]:\text{$I\in \mathcal B(\rho)$ such that $I\cap [k,l]$ is non-empty and closed}\}
\\&\qquad \sqcup \{\textrm{$[k,l]$ with multiplicity $\sharp{\mathcal J}(\rho)$}\},
\\
\mathcal B^o(T_{k,l}(\rho))&=\{I\in \mathcal B^o(\rho) : I\subset [k,l] \},
\\
\mathcal J(T_{k,l}(\rho))&=\emptyset.                                       
\end{aligned}
\end{equation*}

The statements in (a1), (a2), (a3), (a4), (b1), and (b2) can be found in \cite[Proposition~4.3]{BD11}.
Parts (a5), (a6), (a7), (a8), (b3), and (b4) can be proved analogously.
Indeed, the calculation of the kernel of $M(\rho)$ reduces to the description of the space of solutions of the linear system:
\begin{equation*}
\begin{aligned}
\alpha_1(v_1)&=\beta_1(v_3)\\
\alpha_2(v_3)&=\beta_2(v_5)\\
&\ \, \vdots\\
\alpha_m(v_{2m-1})&=\beta_m(v_1)
\end{aligned}
\end{equation*}
wit $v_{2i-1}\in V_{2i-1}.$  This is straight forward for indecomposable representations.

\label{O45}
(a) Let $\rho$ be a $G_{2m}$-representation. Then every decomposition $\rho=\bigoplus_{I\in\mathcal B(\rho)}\rho^G(I)\oplus\bigoplus_{J\in\mathcal J(\rho)}\rho^G(J)$  
induces isomorphisms $\Psi^o$, $\Psi^o_{k,l}$, $\Psi^c$, and $\Psi^c_{k,l}$ such that the diagrams
\begin{equation}\label{E13G}
\vcenter{
\xymatrix{
\ker M(T_{k,l}(\rho))\ar[r]^-{i}     &\ker M(T_{k',l'}(\rho))\ar[r]^-{i'}     &\ker M(\rho)
\\
\kappa[\mathcal B^o(T_{k,l}(\rho))]\ar[u]_\cong^{\Psi^o_{k,l}} \ar[r] &\kappa[\mathcal B^o(T_{k',l'}(\rho))] \ar[u]_\cong^{\Psi^o_{k',l'}}\ar[r] &\kappa[\mathcal B^o(\rho)\sqcup \mathcal J_1(\rho)]\ar[u]_\cong^{\Psi^o}
}} 
\end{equation} 
and
\begin{equation}\label{E14G}
\vcenter{
\xymatrix{
\operatorname{coker} M(T_{k,l}(\rho))\ar[r]^-{j}     &\operatorname{coker} M(T_{k',l'}(\rho))\ar[r]^-{j'}     &\operatorname{coker} M(\rho)
\\
\kappa[\mathcal B^c(T_{k,l}(\rho))]\ar[u]_\cong^{\Psi^c_{k,l}} \ar[r] &\kappa[\mathcal B^c(T_{k',l'}(\rho))] \ar[u]_\cong^{\Psi^c_{k',l'}}\ar[r] &\kappa[\mathcal B^c(\rho)\sqcup \mathcal J_1(\rho)].\ar[u]_\cong^{\Psi^c} 
}} 
\end{equation}
commute for all integers $1\leq k'\leq k\leq l\leq l'\leq m$.









(b) Let $\rho$ be a good $\mathcal Z$-representation. Then every decomposition $\rho=\bigoplus_{I\in\mathcal B(\rho)}\rho(I)\oplus\bigoplus_n\rho^{\mathcal Z}_\infty$, 
where $n=\sharp J(\rho)$, induces isomorphisms $\Psi^o$, $\Psi^o_{k,l}$, $\Psi^c$, and $\Psi^c_{k,l}$ such that the diagrams
\begin{equation}\label{E13Z}
\vcenter{
\xymatrix{
\ker M(T_{k,l}(\rho))\ar[r]^-{i}     &\ker M(T_{k',l'}(\rho))\ar[r]^-{i'}     &\ker M(\rho)
\\
\kappa[\mathcal B^o(T_{k,l}(\rho))]\ar[u]_\cong^{\Psi^o_{k,l}} \ar[r] &\kappa[\mathcal B^o(T_{k',l'}(\rho))] \ar[u]_\cong^{\Psi^o_{k',l'}}\ar[r] &\kappa[\mathcal B^o(\rho)]\ar[u]_\cong^{\Psi^o}
}} 
\end{equation} 
and
\begin{equation}\label{E14Z}
\vcenter{
\xymatrix{
\operatorname{coker} M(T_{k,l}(\rho))\ar[r]^-{j}     &\operatorname{coker} M(T_{k',l'}(\rho))\ar[r]^-{j'}     &\operatorname{coker} M(\rho)
\\
\kappa[\mathcal B^c(T_{k,l}(\rho))]\ar[u]_\cong^{\Psi^c_{k,l}} \ar[r] &\kappa[\mathcal B^c(T_{k',l'}(\rho))] \ar[u]_\cong^{\Psi^c_{k',l'}}\ar[r] &\kappa[\mathcal B^c(\rho)\sqcup \mathcal J(\rho)].\ar[u]_\cong^{\Psi^c} 
}} 
\end{equation}
commute for all integers $k'\leq k\leq l\leq l'$.

\label{P31}
Let $f\colon X\to \mathbb S^1$ be a tame map and $\tilde f\colon\tilde X\to \mathbb R$ its infinite cyclic covering.  
Let $\rho_r= \rho_r(f)$ and $\tilde \rho_r=\rho_r(\tilde f)= \widetilde\rho_r(f)$ be the representations associated with $f$ and $\tilde f$.
One has the following short exact sequences
\begin{equation}\label{EE16}
0\to\operatorname{coker} M((\rho_r)_u)\to H_r(X; (\xi_f,u))\to\ker M((\rho_{r-1})_u)\to0,
\end{equation}
which for $u=1$ becomes 
\begin{equation}\label{EE13}
0\to\operatorname{coker} M(\rho_r)\to H_r(X)\to\ker M(\rho_{r-1})\to0.
\end{equation}
Moreover, one has a short exact sequence of $\kappa[T^{-1},T]$-modules
\begin{equation}\label{F1}
0\to\operatorname{coker} M(\tilde \rho_r)\to H_r(\tilde X)\to\ker M(\tilde \rho_{r-1})\to0.
\end{equation}
These sequences are all compatible with truncations as explained below, see Diagrams~\eqref{DE1} and \eqref{DE30}.

\label{P35}\
Let $f\colon X\to \mathbb S^1$ be a tame map and suppose that for each $r$ a decomposition of the representation $\rho_r(f)$ as a sum of bar code representations and Jordan block and a collection of compatible splittings is provided. 
Then:

a) For $u\in\kappa\setminus 0$ the decompositions and  the  collections of compatible splittings  provide the            
isomorphisms 
\begin{equation*}
\omega_{r,u}\colon\kappa[S_{r,u}(f)] \to H_r(X; (\xi_f ,u))
\end{equation*}
and for any  closed multi interval $K\subset \mathbb S^1$  the            
isomorphisms 
\begin{equation*}
\omega_{r, K, u}\colon\kappa[S_{r,K, u} (f)]\to \mathbb I_r(f;K,u)
\end{equation*}
such that for any pair $K', K$ of closed multi-intervals  in $\mathbb S^1$ with $K'\subset K$,                           
the diagram (\ref {E20}) is commutative.
\begin{equation}\label{E20}
\vcenter{
\xymatrix{
\mathbb I_r(f;K',u) \ar[r]^-{\subseteq} &\mathbb I_r(f;K,u)  \ar[r]^-{\subseteq} &H_r( X; (\xi_f, u))\\
\kappa[S_{r, K', u}(f)]\ar[u]_\cong^{\omega_{r, K', u}}\ar[r] & \kappa[S_{r, K, u}(f)]\ar[u]_\cong^{\omega_{r, K, u}} \ar[r]& \kappa[S_{r, u}(f)]\ar[u]_\cong^{\omega_{r, u}}.
}}
\end{equation}
The horizontal arrows in the bottom line are induced by the inclusions of the sets in brackets.


b) The decompositions and the collection of compatible splittings  provide the isomorphisms
\begin{equation*}
\widetilde\omega_{r}\colon\kappa[\widetilde S_{r}(f)] \to H_r(\tilde X)
\end{equation*}
and for any closed multi interval $K\subset \mathbb R$  the            
isomorphisms 
\begin{equation*}
\widetilde{\omega}_{r, K}\colon\kappa[\widetilde S_{r,K} (f)]\to \mathbb I_r(\tilde f;K)
\end{equation*}
such that for any pair $K', K$ of closed multi-intervals in $\mathbb R$ with $K'\subset K$, the diagram  (\ref {E20b}) is commutative.
\begin{equation}\label{E20b}
\vcenter{
\xymatrix{
\mathbb I_r(\tilde f;K') \ar[r]^{\subseteq} &\mathbb I_r(\tilde f;K)  \ar[r]^{\subseteq} &H_r( \tilde X)\\
\kappa[\widetilde S_{r, K'}(f)]\ar[u]_\cong^{\widetilde \omega_{r,K'}}\ar[r] & \kappa[\widetilde S_{r, K}(f)]\ar[u]_\cong^{\widetilde \omega_{r;K}} \ar[r]& \kappa[\widetilde S_{r}(f)]\ar[u]_\cong^{\widetilde \omega_{r}}.

}}
\end{equation}
The horizontal arrows in the bottom line are induced by the inclusions of the sets in brackets. 
The isomorphism $\tilde\omega_r$ is an isomorphism of $\kappa[T^{-1}, T]$-modules. 


c) The  decompositions and the splittings provide the isomorphisms 
$$
\omega^N_r\colon\kappa[T^{-1}, T]] \ [\mathcal B^c_r(f)\sqcup \mathcal B^o_{r-1}(f)]\to H_r^N(X;\xi_f).
$$

\label{P36} 

a) The decompositions and  the collections of compatible splittings  provide
for any pair of angles $\theta'$, $\theta''$,  $0< \theta'\leq \theta'' <2\pi$, the isomorphisms  
$$
\omega'_{r,[\theta', \theta'']}\colon\kappa[S'_{r, [\theta', \theta'']}(f)] \to H_r(X_{[\theta', \theta'']})
$$ 
such that  for $0<\theta_1\leq \theta_2 \leq \theta_3 \leq \theta_4 <2\pi$
the diagram \eqref{E20c} below is commutative:
\begin{equation}\label{E20c}
\vcenter{
\xymatrix{
H_r(X_{[\theta_2, \theta_3]}) \ar[r]^{v_r} &H_r(X_{[\theta_1, \theta_4]})  \ar[r]^{v'_r} &H_r( X; (\xi_f,u))
\\
\kappa[S'_{r,[\theta_2,\theta_3]}(f)]\ar[u]^{\omega'_{r,[\theta_2,\theta_3]}}\ar[r] & \kappa[S'_{r,[\theta_1,\theta_4]}(f)]\ar[u]^{\omega'_{r,[\theta_1,\theta_4]}} \ar[r]& \kappa[S_{r, u}(f)]\ar[u]^{\omega_{r,u}}.
}}
\end{equation}

b) The decompositions and  the compatible splittings provide for any $a\leq b$, $a$, $b$ real numbers or $\pm\infty$
the isomorphisms 
$$
\tilde \omega'_{r, [a, b]}\colon\kappa[\tilde S'_{r, [a,b]}(f)] \to H_r(\tilde X_{[a,b]})
$$  
such that for $a\leq b\leq c\leq d$ the diagram~\eqref{E20d} below is commutative. 
\begin{equation}\label{E20d}
\vcenter{
\xymatrix{
H_r(\tilde X_{[b,c]})\ar[r] ^{v_r}         &H_r(\tilde X_{[a,d]}) \ar[r]^{v'_r}               &H_r( \tilde X) \\
\kappa[\tilde S'_{r,[b,c]}(f)]\ar[u]^{\tilde\omega_{r,[b,c]}} \ar[r] & \kappa[\tilde S'_{r,[a,d]}(f)]\ar[u]^{\tilde\omega_{r,[a,d]}} \ar[r]& \kappa[\tilde S _r(f)] \ar[u]^{\tilde \omega_{r}}.
}}
\end{equation}
In both diagrams the horizontal arrows in the top line are linear maps induced by the obvious inclusions, while in the bottom line are the canonical linear maps provided by the sets in brackets subsets of a larger set of all bar codes and all $\tilde {\mathcal J}(f)'$s, cf.\ Definition~\ref{D26}. 
A  bar code in the set $S'_{r, \cdots}$ or in ${\tilde S'}_{r,\cdots}$ is sent to itself if  belongs to the next set  and if not, to zero in the next vector space.

\label{O3}\ 
\begin{enumerate}[(a)]
\item\label{O3:a}
For $a\leq a'$ and $b'\leq b$, we have $F^f_r(a,b)\leq F^f_r(a',b')$ and $G^f_r(a,b)\geq G^f_r(a',b')$.    
\item\label{O3:b}
If $|f-g|<\epsilon$ and $a\leq b$ then $F^f_r(a-\epsilon,b+\epsilon)\leq F^g_r(a, b)$ and $G^f_r(a,b) \leq G^g_r(a-\epsilon, b+\epsilon)$.
\item\label{O3:c}
$F^f_r(a,b)=F^{-f}_r(-b,-a)$ and $ G^f_r(a,b)= G^{-f}_r(-b,-a)$.
\end{enumerate}

\label{P51} 
If $f\colon X\to\mathbb R$ is a tame map, then:
\begin{enumerate}[(a)]
\item\label{P51:a}
$F_r^f(a,b)<\infty$.
\item\label{P51:b}
$G^f_r(a,b)<\infty$.


\end{enumerate}

\label{P52}
If $X$ is compact or $f$ is a tame map, then:
\begin{enumerate}[(a)]
\item\label{P52a}
$\mu_r^{F,f}(B)=\mu_r^{G,f}(B)$.  
\item\label{P52b}
Putting $\mu^f_r(B):=\mu_r^{F,f}(B)=\mu_r^{G,f}(B)$, we have $\mu^f_r(B)\geq0$.
\item\label{P52c}
If $B=B_1\cup B_2$, $B_1\cap B_2=\emptyset$ with $B_1$, $B_2$ boxes, then $\mu^f (B)=\mu^f(B_1)+\mu^f(B_2)$.
\item\label{P52d} If if $B'$ and $B''$ are boxes with $B'\subseteq B''$ one has $\mu^f(B')\leq \mu^f(B'')$. 
\end{enumerate}

To ease the writing, we drop $f$ and $r$ from notation and introduce:
\begin{align*}
I_1&:=\dim\bigl(\mathbb I_a\cap\mathbb I^d\bigr),
\\
I_2&:=\dim\bigl((\mathbb I_a\cap\mathbb I^c)/(\mathbb I_a\cap\mathbb I^d)\bigr),
\\
I_3&:=\dim\bigl((\mathbb I_b\cap\mathbb I^d)/(\mathbb I_a\cap \mathbb I^d)\bigr),
\\
I_4&:=\dim\bigl((\mathbb I_b\cap \mathbb I^c)/(\mathbb I_a\cap\mathbb I^c+\mathbb I_b\cap\mathbb I^d)\bigr),
\\
I_5&:=\dim\bigl(\mathbb I_b/(\mathbb I_a+\mathbb I_b\cap\mathbb I^c)\bigr),
\\
I_6&:=\dim\bigl(\mathbb I^c/(\mathbb I_a\cap\mathbb I^c+\mathbb I^d)\bigr), 
\\
I_7&:=\dim\bigl(H/(\mathbb I_b+\mathbb I^c)\bigr),\qquad\textrm{with $H=H_r(X)$.}
\end{align*}
\begin{figure}
\begin{tikzpicture}[scale=0.3]
\draw(0,0) -- (0,20) -- (28,20) -- (28, 0) -- (0,0) node at (1,19) {$H$};
\draw[ultra thick, fill=yellow](4,8) -- (4,18) -- (14,18) -- (14, 8) -- (4,8) node at (5,17) {$\mathbb I_b$};
\draw(6,10) -- (6,16) -- (12,16) -- (12, 10) -- (6,10) node at (7,15) {$\mathbb I_a$};
\draw[ultra thick](8,2) -- (8,14) -- (20,14) -- (20, 2) -- (8,2) node at (19,3) {$\mathbb I^c$};
\draw(10,4) -- (10,12) -- (18,12) -- (18, 4) -- (10,4) node at (17,5) {$\mathbb I^d$};
\end{tikzpicture}
\caption{An illustration for the proof of Proposition~\ref{P52}.}
\label{F:boxes}
\end{figure}
Using Figure~\ref{F:boxes}, it is not hard to notice that: 
\begin{align*}
F(a,d)&=I_1, & G(a,d)&=I_7 +I_6 +I_5 + I_4,
\\
F(b,c)&=I_1+ I_2 + I_3 + I_4, & G(b,c)&=I_7,
\\
F(a,c)&=I_1 + I_2, & G(a,c)&=I_7 +I_5,
\\
F(b,d)&=I_1 +I_3, & G(b,d)&=I_7 + I_6.
\end{align*}
Then we have: 
\begin{multline*}
F(a,d)+F(b,c)-F(a,c)-F(b,d)
\\=I_1+(I_1+I_2+I_3+I_4)-(I_1+I_2)-(I_1+I_3)=I_4
\end{multline*}
and
\begin{multline*}
G(a,d)+G(b,c)-G(a,c)-G(b,d)
\\=(I_7+I_6+I_5+I_4)+I_7-(I_7+I_5)-(I_7+I_6)=I_4.
\end{multline*}
These equalities establish (\ref{P52a}) and (\ref{P52b}).
Part (\ref{P52c}) follows from (\ref {EQQ1}) by inspecting the all relative positions of $B_1$ and $B_2$ as disjoint subsets of $B.$
To check part (\ref{P52d}) one tiles $B''$ as a disjoint union of boxes $B''= B''_1\sqcup B''_2\cdots \sqcup B''_{r-1}\sqcup B''_r$ s.t. $B'$ is one of these boxes and use  item (\ref{P52c}) to inductively derive that $\mu(B'')= \sum _{1\leq i\leq r} \mu(B''_u).$ This implies the result  

\qed

\label{P53}
If $X$ is compact or $f$ is a tame map then:
\begin{enumerate}[(a)]
\item\label{P53a}
For $a<b$ and $c<d$ one has $\mu^f_r\bigl((a,b]\times [c,d)\bigr)=\sum_{a<x\leq b, c\leq y<d}\delta^f_r (x,y)$.
\item\label{P53b}
$F^f_r(b,c)=\sum_{x\leq b, c\leq y}\delta^f_r(x,y)$.  

\item\label{P53c}
$G^f_r(a,d)=\sum_{a\leq x, y\leq d}\delta^f_r(x,y)$. 

\end{enumerate}

\label{O12}
Let  $f\colon X\to \mathbb R$ be a tame map with $\epsilon (f)>0$.  
For any $\epsilon,\epsilon'<\epsilon(f)$ one has:
\begin{equation}\label{E:O12a}
F^f_r(c_i, c_j) = F^f_r(c_i+\epsilon, c_j-\epsilon') = F^f_r(c_{i+1}-\epsilon, c_{j-1}+\epsilon'),
\end{equation} 
and
\begin{equation}\label{E:O12b}
\delta^f _r(c_i, c_j)= F^f_r(c_{i-1}, c_{j+1}) + F^f_r(c_i, c_j)- F^f_r(c_{i-}, c_j) - F^f_r(c_i, c_{j+1}).
\end{equation}

\label{P55}
Let $f\colon X\to\mathbb R$ be a tame map with $\epsilon (f)>0$ and 
$\epsilon<\epsilon(f)/4.$ For  any tame map $g$ with $|f-g|<\epsilon$ and any $(a,b)\in\operatorname{supp}\delta^f_r$ the following holds:
\begin{enumerate}[(a)]
\item\label{P55a}
$\operatorname{supp}(\delta^f_r)\cap B(a,b;2\epsilon)\equiv (a,b)$                                                                    
\item\label{P55b}
$\sharp\bigl(\operatorname{supp}(\delta^g_r)\cap\bigl(\bigsqcup_{(a,b)\in\operatorname{supp}\delta^f_r}B(a,b;2\epsilon)\bigr)\bigr)=\sharp\operatorname{supp}(\delta^f_r)$.
\end{enumerate}
In particular, if the cardinality of the supports\footnote{Recall that the cardinality of the support is the sum of multiplicity of the elements in the support.} 
of $\delta^f_r$ and $\delta^g_r$ are equal                                                                                 
and $|g-f|<\epsilon$, then the support of $\delta^g_r$ lies in an $\epsilon$-neighborhood\footnote{Here $\epsilon$-neighborhood of $(a,b)$ 
means the domain $(a-\epsilon,a+\epsilon)\times (b-\epsilon,b+\epsilon)$.} of the support of $\delta^f_r$.

Item~(\ref{P55a}) follows from the definition of $\delta^f_r$.
To prove item~(\ref{P55b}) observe that if $(a,b)\in\operatorname{supp}\delta^f$ both numbers have to be critical values, hence the $a=c_i$, $b=c_j$. 
In view of Proposition~\ref{O12}, for any $\epsilon',\epsilon''<\epsilon(f)$ one has:
\begin{equation}\label{E37}
\begin{aligned}
F^f_r(c_{i-1}, c_{j+1})&=F^f_r(a-\epsilon', b+\epsilon'')\\                                                                                      
F^f_r(c_i, c_j)&=F^f_r(a+\epsilon', b-\epsilon'')\\                                                                                     
F^f_r(c_i, c_{j+1})&=F^f_r(a+\epsilon', b+\epsilon'')\\                                                                                       
F^f_r(c_{i-1}, c_j)&=F^f_r(a-\epsilon', b-\epsilon'')                                                                                     
\end{aligned}
\end{equation}
Since $|f-g|<\epsilon$, in view of Observation~\ref{O3} one has:
\begin{equation}\label{E38}
\begin{array}{rcccl}
F^f_r(a-3\epsilon,b+3\epsilon)&\leq&F^g_r(a-2\epsilon,b+2\epsilon)&\leq&F^f_r(a- \epsilon,b+\epsilon) \\
F^f_r(a+ \epsilon,b- \epsilon)&\leq&F^g_r(a+2\epsilon,b-2\epsilon)&\leq&F^f_r(a+3\epsilon,b-3\epsilon)\\
F^f_r(a+ \epsilon,b+3\epsilon)&\leq&F^g_r(a+2\epsilon,b+2\epsilon)&\leq&F^f_r(a+3\epsilon,b+\epsilon) \\
F^f_r(a-3\epsilon,b- \epsilon)&\leq&F^g_r(a-2\epsilon,b-2\epsilon)&\leq&F^f_r(a- \epsilon,b-3\epsilon)
\end{array}
\end{equation}
Since $\epsilon<\epsilon(f)/4$, equations~\eqref{E37} and \eqref{E38} imply:
\begin{equation}\label{E39}
\begin{aligned}
F^g_r(a-2\epsilon, b+2\epsilon)&=F^f_r(c_{i-1}, c_{j+1})\\
F^g_r(a+2\epsilon, b-2\epsilon)&=F^f_r(c_i,c_j)\\
F^g_r(a+2\epsilon, b+2\epsilon)&=F^f_r(c_{i},c_{j+1})\\                                                                   
F^g_r(a-2\epsilon, b-2\epsilon)&=F^f_r(c_{i-1}, c_{j})                                                                       
\end{aligned}
\end{equation}
In view of Proposition~\ref{P53} we have
\begin{equation*}
\begin{aligned}
\sharp\bigl(\operatorname{supp}(\delta^g_r)\cap B(a,b;2\epsilon)\bigr)
&=\mu^g_r\bigl(B(a,b;2\epsilon)\bigr)
\\&=F^g_r(a-2\epsilon,b+2\epsilon)+F^g_r(a+2\epsilon,b-2\epsilon)
\\&\qquad-F^g_r(a-2\epsilon,b-2\epsilon)-F^g_r(a+2\epsilon,b+2\epsilon).
\end{aligned}
\end{equation*}
Using the equations~\eqref{E39} and the equation~\eqref{E:O12b} in Proposition~\ref{O12} one derives
$$
\sharp\bigl(\operatorname{supp}(\delta^g_r)\cap B(a,b;2\epsilon)\bigr)=\sharp\bigl(\operatorname{supp}(\delta^f_r)\cap B(a,b;2\epsilon)\bigr)=\delta^f_r(a,b),
$$ 

\qed

We check the case of an angle valued map $f\colon X\to \mathbb S^1$ only. 
